@Override
public void endElement(String uri, String localName, String qName) throws SAXException {
    String uc = (qName == null) ? "" : qName.toUpperCase(Locale.ENGLISH);
    if (uc.equals(STYLE)) {
        styleDepth--;
    }
    if (uc.equals(SCRIPT)) {
        scriptDepth--;
    }
}
